function combinationSum(candidates, target) {
  const nums = [...candidates].sort((a, b) => a - b)
  const result = []
  const path = []
  function backtrack(start, remaining) {
    if (remaining === 0) {
      result.push([...path])
      return
    }
    for (let i = start; i < nums.length; i++) {
      if (nums[i] > remaining) break
      path.push(nums[i])
      backtrack(i, remaining - nums[i])
      path.pop()
    }
  }
  backtrack(0, target)
  return result
}

