function generateParenthesis(n) {
  const result = []
  function backtrack(s, opened, closed) {
    if (s.length === 2 * n) {
      result.push(s)
      return
    }
    if (opened < n) backtrack(s + '(', opened + 1, closed)
    if (closed < opened) backtrack(s + ')', opened, closed + 1)
  }
  backtrack('', 0, 0)
  return result
}

