def letter_combinations(digits):
    keys = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl",
            "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    if not digits:
        return []
    out = []
    path = []

    def choose(i):
        if i == len(digits):
            out.append("".join(path))
            return
        for letter in keys[digits[i]]:
            path.append(letter)         # choose
            choose(i + 1)               # explore
            path.pop()                  # undo

    choose(0)
    return out
